import React, { useEffect, useRef, useState } from "react";
import { Html5Qrcode } from "html5-qrcode";

function QRScanner() {
  const scannerRef = useRef(null);
  const [student, setStudent] = useState(null);
  const [status, setStatus] = useState("");
  const [isScanning, setIsScanning] = useState(false);
  const isProcessing = useRef(false);

  // Initialize scanner on mount
  useEffect(() => {
    scannerRef.current = new Html5Qrcode("reader");
    
    // Cleanup on unmount
    return () => {
      if (scannerRef.current && scannerRef.current.isScanning) {
        scannerRef.current.stop().catch(() => {});
      }
    };
  }, []);

  const startScanner = async () => {
    try {
      setStatus("");
      setStudent(null);
      await scannerRef.current.start(
        { facingMode: "environment" },
        {
          fps: 20,
          qrbox: { width: 250, height: 250 },
        },
        onScanSuccess
      );
      setIsScanning(true);
    } catch (err) {
      console.error("Scanner failed:", err);
      alert("Could not start camera. Please ensure it isn't used by another app.");
    }
  };

  const stopScanner = async () => {
    if (scannerRef.current && scannerRef.current.isScanning) {
      await scannerRef.current.stop();
      setIsScanning(false);
    }
  };

  const onScanSuccess = async (decodedText) => {
    if (isProcessing.current) return;
    isProcessing.current = true;

    try {
      // Step 1: Verify User & Get Event Details
      const verify = await fetch(`http://localhost:5000/verify-user/${decodedText}`);
      const verifyData = await verify.json();

      if (!verifyData.success) {
        setStudent(null);
        setStatus("notfound");
      } else {
        // Assuming your backend returns { user: { name, event_name, ... } }
        setStudent(verifyData.user);

        // Step 2: Mark Attendance
        const attendance = await fetch(
          `http://localhost:5000/mark-attendance/${decodedText}`,
          { method: "PUT" }
        );
        const attendanceData = await attendance.json();
        setStatus(attendanceData.success ? "success" : "already");
      }
    } catch (err) {
      console.error(err);
      setStatus("servererror");
    } finally {
      // Cooldown to prevent multiple scans of the same code
      setTimeout(() => {
        isProcessing.current = false;
      }, 3000);
    }
  };

  return (
    <div style={{ textAlign: "center", marginTop: "20px", padding: "20px" }}>
      <h2 style={{ color: "#333" }}>Event Attendance Scanner</h2>

      {/* Control Buttons */}
      <div style={{ marginBottom: "20px" }}>
        {!isScanning ? (
          <button 
            onClick={startScanner}
            style={{ padding: "12px 24px", backgroundColor: "#28a745", color: "white", border: "none", borderRadius: "5px", cursor: "pointer", fontSize: "16px" }}
          >
            Start Scanning
          </button>
        ) : (
          <button 
            onClick={stopScanner}
            style={{ padding: "12px 24px", backgroundColor: "#dc3545", color: "white", border: "none", borderRadius: "5px", cursor: "pointer", fontSize: "16px" }}
          >
            Stop Scanning
          </button>
        )}
      </div>

      {/* Scanner Box */}
      <div
        id="reader"
        style={{
          width: "100px",
          maxWidth: "400px",
          margin: "auto",
          border: isScanning ? "4px solid #28a745" : "4px solid #ccc",
          borderRadius: "10px",
          overflow: "hidden",
          display: isScanning ? "block" : "none"
        }}
      ></div>

      {!isScanning && (
        <div style={{ height: "300px", display: "flex", alignItems: "center", justifyContent: "center", backgroundColor: "#f8f9fa", maxWidth: "400px", margin: "auto", borderRadius: "10px", border: "1px dashed #ccc" }}>
          <p>Camera is Offline</p>
        </div>
      )}

      {/* Admin Display Area */}
      <div style={{ marginTop: "30px", padding: "20px", border: "1px solid #eee", borderRadius: "10px", minHeight: "150px" }}>
        {status === "notfound" && <h3 style={{ color: "red" }}>❌ User Not Registered</h3>}
        
        {student && (
          <div>
            <h2 style={{ margin: "0", color: "#007bff" }}>{student.name}</h2>
            <p style={{ fontSize: "18px", fontWeight: "bold" }}>
              Event: <span style={{ color: "#555" }}>{student.event_name || "N/A"}</span>
            </p>
            
            {status === "success" && (
              <div style={{ padding: "10px", backgroundColor: "#d4edda", color: "#155724", borderRadius: "5px" }}>
                ✔ Attendance Confirmed!
              </div>
            )}
            
            {status === "already" && (
              <div style={{ padding: "10px", backgroundColor: "#fff3cd", color: "#856404", borderRadius: "5px" }}>
                ⚠️ Already checked in.
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

export default QRScanner;
